   "passage": "学級新聞のしめ切りは、明日の朝だった。新聞係のぼくたち三人は、放課後の教室で記事の仕上げをしていた。今回は、学校のとなりにある古い商店をしょうかいする記事だ。\n\n「この『創業《そうぎょう》百年』って、本当かな。」\n記事を読み返していたゆうきが、急に顔を上げた。\n「店のおばあさんが、そう言ってたじゃないか。」\nぼくが答えると、ゆうきは首をふった。\n「『百年くらい』って言ってたよ。くらいと百年はちがうよ。たしかめに行ってくる。」\n\nゆうきは、教室を出ていった。もう一人の係のまいが、ため息をついた。\n「ゆうきくんって、こういうとき、ぜったいゆずらないよね。」\nぼくも同じ気持ちだった。少しくらいちがっても、だれも気にしないのに。\n\n三十分後、ゆうきは息を切らしてもどってきた。手には、古い写真のコピーがあった。\n「店ができたのは、九十八年前だって。それに、おもしろい話も聞けたんだ。」\n写真には、店の前で笑う若《わか》い女の人がうつっていた。おばあさんのお母さんだという。\n\n次の日、できあがった新聞は、クラスのみんなに読まれた。おばあさんも、教室まで見に来てくれた。ゆうきは、そっぽを向いていたが、耳が赤くなっていた。",
